() => {
  return new Promise(res => {
    const timer = setTimeout(() => {
      clearTimeout(timer);
      const level = Math.floor(Math.random() * 6) + 1;
      const result = [1, 2, 3].map(i => {
        const key = level ? 'label_' + i + '_' + level : 'label_' + i;
        return {
          label: key,
          value: key
        };
      });
      res(result);
    }, 3000);
  });
}
